use spatial_types::{Point3, Provenance, SpatialError, StandardUncertainty};
#[derive(Debug,Clone,Copy,PartialEq,Eq)]pub enum Conformance{Pass,Fail,Indeterminate}
#[derive(Debug,Clone,PartialEq)]pub struct DistanceMeasurement{pub a:Point3,pub b:Point3,pub measured:f64,pub nominal:Option<f64>,pub lower_tolerance:Option<f64>,pub upper_tolerance:Option<f64>,pub standard_uncertainty:StandardUncertainty,pub coverage_factor:f64,pub conformance:Option<Conformance>,pub provenance:Provenance}
impl DistanceMeasurement{
pub fn evaluate(a:Point3,b:Point3,nominal:Option<f64>,lower:Option<f64>,upper:Option<f64>,uncertainty:StandardUncertainty,coverage_factor:f64,provenance:Provenance)->Result<Self,SpatialError>{if !coverage_factor.is_finite()||coverage_factor<=0.0{return Err(SpatialError::Degenerate("coverage factor must be positive"));}let measured=a.distance(b);let conformance=match(nominal,lower,upper){(Some(n),Some(lo),Some(hi))=>{let min=n+lo;let max=n+hi;let expanded=uncertainty.0*coverage_factor;Some(if measured-expanded>=min&&measured+expanded<=max{Conformance::Pass}else if measured+expanded<min||measured-expanded>max{Conformance::Fail}else{Conformance::Indeterminate})},_=>None};Ok(Self{a,b,measured,nominal,lower_tolerance:lower,upper_tolerance:upper,standard_uncertainty:uncertainty,coverage_factor,conformance,provenance})}}
#[cfg(test)]mod tests{use super::*;use spatial_types::{ArtifactId};fn prov()->Provenance{Provenance{method:"point-distance".into(),implementation_version:"1".into(),source_artifacts:vec![ArtifactId("scan".into())],parameters:"{}".into()}}
#[test]fn uncertainty_overlap_is_indeterminate(){let m=DistanceMeasurement::evaluate(Point3::new(0.,0.,0.).unwrap(),Point3::new(10.09,0.,0.).unwrap(),Some(10.),Some(-0.1),Some(0.1),StandardUncertainty::new(0.02).unwrap(),2.,prov()).unwrap();assert_eq!(m.conformance,Some(Conformance::Indeterminate));}
}
